<h1>Đơn hàng của tôi</h1><?php if (!$orders): ?><p>Bạn chưa có đơn hàng.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Mã</th><th>Tổng tiền</th><th>Trạng thái</th><th>Ngày tạo</th><th></th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td>#<?= (int) $order['id'] ?></td><td><?= number_format((float) $order['total_amount'], 0, ',', '.') ?> ₫</td><td><?= View::escape($order['status']) ?></td><td><?= View::escape($order['created_at']) ?></td><td><a href="<?= BASE_URL ?>/?r=orders/detail/<?= (int) $order['id'] ?>">Xem</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
